compile.workshop:
variables {
    global:
        0: g
}

rule ("host and local components") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(g, Y Component Of(Host Player));
        Set Global Variable(g, Z Component Of(Local Player));
    }
}

rule ("death components") {
    event {
        Player Died;
        All;
        All;
    }
    actions {
        Set Global Variable(g, X Component Of(Attacker));
        Set Global Variable(g, Z Component Of(Victim));
    }
}

